package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_value_TriageGen1Test {

    private JsonWriter jsonWriter;
    private StringWriter stringWriter;

    @Before
    public void setUp() throws IOException {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_WhenNaN_ThrowsIllegalArgumentException() throws IOException {
        jsonWriter.value(Double.NaN);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_WhenPositiveInfinity_ThrowsIllegalArgumentException() throws IOException {
        jsonWriter.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_WhenNegativeInfinity_ThrowsIllegalArgumentException() throws IOException {
        jsonWriter.value(Double.NEGATIVE_INFINITY);
    }

    @Test
    public void testValue_WhenValidFiniteDouble_CreatesCorrectJson() throws IOException {
        double value = 123.456;
        jsonWriter.value(value);

        assertEquals(Double.toString(value), stringWriter.toString().trim());
    }

    @Test
    public void testValue_WhenZero_CreatesCorrectJson() throws IOException {
        double value = 0.0;
        jsonWriter.value(value);

        assertEquals(Double.toString(value), stringWriter.toString().trim());
    }

    @Test
    public void testValue_WhenNegativeDouble_CreatesCorrectJson() throws IOException {
        double value = -789.012;
        jsonWriter.value(value);

        assertEquals(Double.toString(value), stringWriter.toString().trim());
    }

    @Test
    public void testValue_WhenPositiveDouble_CreatesCorrectJson() throws IOException {
        double value = 3.14159;
        jsonWriter.value(value);

        assertEquals(Double.toString(value), stringWriter.toString().trim());
    }

    @Test
    public void testValue_WhenZeroValue_CallsBeforeValue() throws IOException {
        jsonWriter.value(0.0);

        ArgumentCaptor<Void> captor = ArgumentCaptor.forClass(Void.class);
        verify(jsonWriter, times(1)).beforeValue(captor.capture());
        assertTrue(captor.getValue() == null); // Ensure no exception thrown
    }

    @Test
    public void testValue_WhenPositiveValue_CallsBeforeValue() throws IOException {
        jsonWriter.value(1.23);

        ArgumentCaptor<Void> captor = ArgumentCaptor.forClass(Void.class);
        verify(jsonWriter, times(1)).beforeValue(captor.capture());
        assertTrue(captor.getValue() == null); // Ensure no exception thrown
    }

    @Test
    public void testValue_WhenNegativeValue_CallsBeforeValue() throws IOException {
        jsonWriter.value(-1.23);

        ArgumentCaptor<Void> captor = ArgumentCaptor.forClass(Void.class);
        verify(jsonWriter, times(1)).beforeValue(captor.capture());
        assertTrue(captor.getValue() == null); // Ensure no exception thrown
    }

    // Add any additional utility methods needed for testing if necessary
}
